def preserve_legacy_tournaments(apps, schema_editor):
    alias = schema_editor.connection.alias
    apps.get_model("tournaments", "Tournament").objects.using(alias).update(scoring_method="roi", daily_coupon_limit=0)
    Link = apps.get_model("tournaments", "TournamentCoupon")
    for link in Link.objects.using(alias).select_related("coupon").prefetch_related("coupon__predictions").iterator(chunk_size=500):
        predictions = list(link.coupon.predictions.all())
        coefficient = Decimal("1") if predictions else Decimal("0")
